// src/client/pathutil.ts
function isAbs(p) {
  if (/^[A-Za-z]:[\\/]/.test(p)) return true;
  if (p.startsWith("\\\\")) return true;
  if (p.startsWith("/")) return true;
  return false;
}
function joinPath(base3, rel) {
  const relTrim = rel.replace(/^[\\/]+/, "").replace(/[\\/]+$/, "");
  const sep = base3.includes("\\") ? "\\" : "/";
  if (base3 === "/" || base3 === "\\") return base3 + relTrim;
  if (/^[A-Za-z]:[\\/]$/.test(base3)) return base3 + relTrim;
  const baseTrim = base3.replace(/[\\/]+$/, "");
  if (!baseTrim) return relTrim || sep;
  return baseTrim + sep + relTrim;
}
function parentPathOf(p) {
  const idx = Math.max(p.lastIndexOf("/"), p.lastIndexOf("\\"));
  if (idx < 0) return p;
  if (idx === 0) return p[0];
  if (idx === 2 && /^[A-Za-z]:[\\/]/.test(p)) return p.slice(0, 3);
  return p.slice(0, idx);
}
function basenameOf(p) {
  const idx = Math.max(p.lastIndexOf("/"), p.lastIndexOf("\\"));
  return idx < 0 ? p : p.slice(idx + 1);
}
function relativeTo(base3, p) {
  const norm = (s) => s.replace(/\\/g, "/").replace(/\/+$/, "");
  const b = norm(base3);
  const t = norm(p);
  if (!b) return t.replace(/^\/+/, "");
  const bl = b.toLowerCase();
  const tl = t.toLowerCase();
  if (tl === bl) return ".";
  if (tl.startsWith(bl + "/")) return t.slice(b.length + 1);
  return t.replace(/^\/+/, "");
}

